// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzz the caller address
    function testFuzz_property(address caller) public {
        // keep wide: exclude zero address only because vm.prank(address(0)) is allowed but owner will be address(0) initially
        // No tight constraints so the fuzzer can find owner vs non-owner cases

        // get the contract's owner getter
        address initialOwner = c.owner();

        bool ok;
        // Simulate the call from `caller` and observe whether it reverts
        // Use try/catch to capture revert behaviour
        vm.prank(caller);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract enforces that only the owner may call owned():
        // So for ALL inputs, ok == (caller == initialOwner)
        // The mutant inverts the check and will make this assertion fail for inputs where caller != initialOwner (or where caller == initialOwner depending on mutant).
        assertTrue(ok == (caller == initialOwner));
    }
}
